const { execution, workflow } = $json;
const error = execution?.error ?? {};
const subject = `🚨 Falló "${workflow?.name ?? 'workflow'}" en n8n`;
const html = `<p>El workflow <b>${workflow?.name}</b> falló.</p>
<ul>
<li>Nodo: <b>${execution?.lastNodeExecuted ?? '—'}</b></li>
<li>Error: ${error.message ?? '—'}</li>
<li>Ejecución: ${execution?.url ? `<a href="${execution.url}">${execution.id}</a>` : execution?.id ?? '—'}</li>
</ul>
<p style="color:#666">Alerta automática de Libra · n8n</p>`;
return { json: { to: $env.ADMIN_EMAIL, subject, html } };
